import os

class Compiler():
    AS          = "as"
    CC          = "gcc"
    CXX         = "g++"
    LD          = "ld"

    ASFLAGS     = ""
    CFLAGS      = ""
    CXXFLAGS    = ""
    CPPFLAGS    = ""
    LDFLAGS     = ""

class Target():
    SRCDIR              = ""
    SRC                 = []

    TARGETNAME          = ""

    COMPILER: Compiler  = None

    OUT                 = "a.out"
    BUILDDIR            = "build"
    RECREATE_SRC_TREE   = True

class Build():
    def __init__(self):
        self.targets = []

    def addTarget(self, target):
        self.targets.append(target)

    def addTargets(self, targets):
        for t in targets: self.targets.append(t)

    def build(self):
        for t in self.targets:
            print(f"Building {t.TARGETNAME}...")
            os.makedirs(t.BUILDDIR, exist_ok=True)
            outs = ""
            for src in t.SRC:
                if (src.endswith(".s") or src.endswith(".S")) and t.COMPILER.AS != "":
                    os.system(f"{t.COMPILER.AS} {t.COMPILER.ASFLAGS} {os.path.join(t.SRCDIR, src)} -o {os.path.join(t.BUILDDIR, os.path.join(t.SRCDIR, src).replace("/", "_"))}.o")
                    outs += f" {os.path.join(t.BUILDDIR, os.path.join(t.SRCDIR, src).replace("/", "_"))}.o"
                elif src.endswith(".c") and t.COMPILER.CC != "":
                    os.system(f"{t.COMPILER.CC} -c {t.COMPILER.CFLAGS} {t.COMPILER.CPPFLAGS} {os.path.join(t.SRCDIR, src)} -o {os.path.join(t.BUILDDIR, os.path.join(t.SRCDIR, src).replace("/", "_"))}.o")
                    outs += f" {os.path.join(t.BUILDDIR, os.path.join(t.SRCDIR, src).replace("/", "_"))}.o"
                elif src.endswith(".cpp") and t.COMPILER.CXX != "":
                    os.system(f"{t.COMPILER.CXX} -c {t.COMPILER.CXXFLAGS} {t.COMPILER.CPPFLAGS} {os.path.join(t.SRCDIR, src)} -o {os.path.join(t.BUILDDIR, os.path.join(t.SRCDIR, src).replace("/", "_"))}.o")
                    outs += f" {os.path.join(t.BUILDDIR, os.path.join(t.SRCDIR, src).replace("/", "_"))}.o"
            if t.COMPILER.LD != "":
                os.system(f"{t.COMPILER.LD} {t.COMPILER.LDFLAGS} {outs} -o {t.OUT}")
